cd /tmp/work && cat >> load.py <<'EOF'

# stuck-sensor glitch windows (UTC minutes), excluded from fits
GLITCH = {'TURB_OUTPUT_01': (1080, 1104), 'STEAM_PRES_01': (1200, 1219), 'COOLING_PRES_01': (1450, 1474)}
df['glitch'] = False
for sid, (a, b) in GLITCH.items():
    df.loc[(df.sensor_id==sid)&(df.t_utc>=a)&(df.t_utc<=b), 'glitch'] = True
df['dir'] = 0
def fit_baseline(sid, tmax=1380, col='t_utc'):
    s = df[(df.sensor_id==sid)&(~df.glitch)&(df[col]<tmax)]
    t = s[col].values; y = s.value.values
    w = 2*np.pi/1440
    X = np.c_[np.ones_like(t), np.sin(w*t), np.cos(w*t)]
    beta, *_ = np.linalg.lstsq(X, y, rcond=None)
    res = y - X@beta
    return beta, res.std()
def baseline(beta, t):
    w = 2*np.pi/1440
    return beta[0] + beta[1]*np.sin(w*t) + beta[2]*np.cos(w*t)
EOF
