import sys; sys.path.insert(0,'/tmp/work')
from fit import *
SUBS = ['COOLING','PRIMARY_LOOP','CORE','STEAM_GEN','TURBINE']

def joint_profile(sub, col='t_phys', lo=1200, end=None, grid=None, diurnal=True):
    end = end or END[sub]
    grid = grid if grid is not None else np.arange(1380, 1560, 0.25)
    data = []
    for sid in meta.index[meta.subsystem==sub]:
        if diurnal:
            t, r, sdn = resid(sid, col)
        else:
            s = df[(df.sensor_id==sid)&(~df.glitch)].sort_values(col)
            hw = (meta.normal_max[sid]-meta.normal_min[sid])/2
            t = s[col].values; r = (s.value.values - s.value[s[col]<1380].mean())/hw
            sdn = r[t<1380].std()
        m = (t>=lo)&(t<=end)
        data.append((t[m], r[m]/sdn))   # whiten by baseline noise
    sse = []
    for t0 in grid:
        tot = 0
        for t, z in data:
            X = np.c_[np.ones_like(t), np.maximum(0, t-t0)]
            beta, *_ = np.linalg.lstsq(X, z, rcond=None)
            tot += ((z-X@beta)**2).sum()
        sse.append(tot)
    sse = np.array(sse)
    i = sse.argmin()
    # 95% profile interval: delta SSE < 3.84 (z whitened, sigma~1)
    ok = grid[sse - sse[i] < 3.84]
    return grid[i], ok.min(), ok.max()

if __name__ == '__main__':
    for col in ['t_phys','t_utc']:
        print('==', col)
        res = {s: joint_profile(s, col) for s in SUBS}
        for s, (b, l, h) in sorted(res.items(), key=lambda kv: kv[1][0]):
            print(f"  {s:13s} t0={b:7.2f} (95% CI {l:7.2f}-{h:7.2f})  = {pd.Timestamp('2024-01-15')+pd.Timedelta(minutes=b)}")
EOF
